/* inkling_chat_gate -- the Inkling-Small frontend graded against the references (L295 F5 / L294 E6):
 * the shared BPE engine in its tiktoken configuration against HF tokenizers on tokenizer.json, the renderer
 * against vLLM's native Inkling renderer, the output-parser kit's Inkling configuration against vLLM's
 * parser engine.  Model-free; seconds.
 *
 * Goldens: tests/test-vectors/inkling/, generated by tests/inkling/gen_inkling_goldens.py (meta.json records
 * the versions, the vLLM revision and the input hashes).
 *
 *   T0 configuration              the rank file loads as the o200k pattern tokenizer.json's regex names;
 *                                 its ids, stop ids and special tokens are the checkpoint's
 *   T1 adversarial strings        encode(text) == HF ids
 *   T2 span guard                 encode(text, client spans) == tokenizers' components, added tokens cut only
 *                                 outside the spans
 *   T3 every scalar value         per-4096-codepoint chunk: count + sha1(ids) == HF
 *   T4 a corpus                   count + sha1(ids) == HF per row   (--calib)
 *   R1 render hand cases          text == vLLM's (as strings), guarded ids == vLLM's with client text
 *                                 never matching a special token, == vLLM's ids when no client text spells
 *                                 one; refusals where vLLM raises; the effort map and its text
 *   R2 render corpus              every L216 case, two configurations: sha1(text), sha1(guarded ids) per file
 *                                 (--cases)
 *   P1 output parser units        vLLM's reading of hand outputs, whole / byte-by-byte / random chunking,
 *                                 the streamed events consistent with the reading
 *   P2 output parser corpus       every assistant turn of the corpus as sampled: vLLM's reading, sha1 per
 *                                 file, three chunkings   (--cases)
 *   S1 live pieces (E6)           the server's suffix hooks and the engine's chat front are the renderer's
 *                                 own writer: prompt + sampled turn + tail == the full render at every
 *                                 assistant turn of the corpus; the parser's raw span of a turn's calls is
 *                                 the call-block finder's key where the turn sits; a raw replay of a
 *                                 canonical turn is that turn; hand cases for the finder and the refusals
 *                                 (corpus with --cases)
 *
 * usage: inkling_chat_gate --tok DIR --vectors DIR [--cases DIR] [--calib FILE]
 *        DIR = the checkpoint's tiktoken/tokenizer.model, tokenizer.json, tokenizer_config.json,
 *              special_tokens_map.json and config.json */
#include <map>
#include <random>

#include "bpe_gate_util.h"
#include "../src/lib/inkling_chat.h"

/* T3's context for one codepoint c (tests/inkling/gen_inkling_goldens.py sweep_text) */
static std::string inkling_sweep_context(const std::string &c) {
    return "x" + c + c + c + " " + c + "1'" + c + "A" + c + "b" + c + "'S/" + c + "\n";
}

/* ---- T0 ----------------------------------------------------------------------------------------------- */

static void t0_configuration(const bpe_tokenizer *t, const std::string &tok_dir, const pyjson_value &meta) {
    CHECK(bpe_tokenizer_n_tokens(t) == atoi(meta.get("n_tokens")->num.c_str()), "token count %d vs HF %s",
          bpe_tokenizer_n_tokens(t), meta.get("n_tokens")->num.c_str());
    CHECK(!strcmp(bpe_tokenizer_pattern(t)->name, "o200k"), "pattern %s", bpe_tokenizer_pattern(t)->name);
    /* tokenizer.json's Split regex is the registered o200k pattern: the rank file's split is HF's */
    std::string tj;
    pyjson_value doc;
    char err[200];
    CHECK(read_file(tok_dir + "/tokenizer.json", &tj) && pyjson_parse(tj.data(), tj.size(), &doc, err, sizeof err),
          "T0: no tokenizer.json");
    const pyjson_value *steps = doc.get("pre_tokenizer") ? doc.get("pre_tokenizer")->get("pretokenizers") : NULL;
    const pyjson_value *rx = steps && !steps->a.empty() && steps->a[0].get("pattern")
                                 ? steps->a[0].get("pattern")->get("Regex") : NULL;
    CHECK(rx && bpe_pretok_by_regex(rx->s.c_str()) == bpe_tokenizer_pattern(t),
          "tokenizer.json's pre-tokenizer regex is not the registered o200k pattern");
    CHECK(doc.get("normalizer") && doc.get("normalizer")->kind == pyjson_value::NUL,
          "tokenizer.json has a normalizer (the tiktoken configuration has none)");
    const pyjson_value *model = doc.get("model");
    CHECK(model && model->get("ignore_merges") && model->get("ignore_merges")->b,
          "tokenizer.json's BPE does not ignore merges (tiktoken's whole-piece lookup)");
    /* the stop id: config.json's eos_token_id */
    const int eos = bpe_tokenizer_added_id(t, meta.get("eos")->s.c_str());
    CHECK(bpe_tokenizer_stop_ids(t) == std::vector<int>{eos}, "stop ids are not [%s]", meta.get("eos")->s.c_str());
    /* the special tokens: each an added token; the grammar's markers plus its dropped ones are exactly them */
    const out_grammar &g = inkling_output_grammar();
    std::vector<std::string> gram = g.markers;
    gram.insert(gram.end(), g.dropped.begin(), g.dropped.end());
    std::sort(gram.begin(), gram.end());
    std::vector<std::string> specials;
    for (const auto &s : meta.get("special_tokens")->a) {
        specials.push_back(s.s);
        CHECK(bpe_tokenizer_added_id(t, s.s.c_str()) >= 0, "special token %s is not an added token", s.s.c_str());
    }
    std::sort(specials.begin(), specials.end());
    CHECK(gram == specials, "the output grammar's markers + dropped are not special_tokens_map's tokens");
    printf("T0 configuration: %d ids, pattern %s, stop %d %s, %zu special tokens\n", bpe_tokenizer_n_tokens(t),
           bpe_tokenizer_pattern(t)->name, eos, meta.get("eos")->s.c_str(), specials.size());
}

/* ---- the API conversation -> renderer input ---------------------------------------------------------- */

struct conv {
    std::vector<inkling_msg_in> msgs;
    std::vector<std::vector<inkling_tool_call_in>> calls;
    std::vector<std::vector<inkling_part_in>> parts;
    std::vector<std::string> store;   /* owned strings; reserved up front so c_str() stays put */
    std::string tools;
    bool has_tools = false;
};

static const char *keep(conv *c, const std::string &s) {
    c->store.push_back(s);
    return c->store.back().c_str();
}

static const char *opt_str(conv *c, const pyjson_value *v) {
    return v && v->kind == pyjson_value::STR ? keep(c, v->s) : NULL;
}

static void build_conv(const pyjson_value &messages, const pyjson_value *tools, conv *c) {
    size_t strings = 1;
    for (const auto &m : messages.a) {
        strings += 8;
        if (const pyjson_value *tc = m.get("tool_calls")) strings += 3 * tc->a.size();
        if (const pyjson_value *ct = m.get("content"); ct && ct->kind == pyjson_value::ARR) strings += ct->a.size();
    }
    c->store.reserve(strings);
    c->msgs.resize(messages.a.size());
    c->calls.resize(messages.a.size());
    c->parts.resize(messages.a.size());
    for (size_t i = 0; i < messages.a.size(); i++) {
        const pyjson_value &m = messages.a[i];
        inkling_msg_in &q = c->msgs[i];
        q = {};
        q.role = opt_str(c, m.get("role"));
        const pyjson_value *content = m.get("content");
        q.content = opt_str(c, content);
        if (content && content->kind == pyjson_value::ARR) {
            for (const auto &part : content->a) {
                if (part.kind == pyjson_value::STR) {
                    c->parts[i].push_back({false, keep(c, part.s)});
                    continue;
                }
                const pyjson_value *type = part.get("type");
                const bool image = type && (type->s == "image" || type->s == "input_image" || type->s == "image_url");
                const pyjson_value *t = part.get("text");
                c->parts[i].push_back({image, image ? NULL : opt_str(c, t)});
            }
            q.parts = c->parts[i].data();
            q.n_parts = (int)c->parts[i].size();
        }
        q.reasoning = opt_str(c, m.get("reasoning_content"));
        q.name = opt_str(c, m.get("name"));
        q.tool_call_id = opt_str(c, m.get("tool_call_id"));
        if (const pyjson_value *tcs = m.get("tool_calls")) {
            for (const auto &tc : tcs->a) {
                const pyjson_value *fn = tc.get("function");
                if (!fn) fn = &tc;
                const pyjson_value *args = fn->get("arguments");
                std::string a;
                if (args && args->kind == pyjson_value::STR) a = args->s;
                else if (args && args->kind != pyjson_value::NUL) pyjson_dump(*args, &a);
                c->calls[i].push_back({opt_str(c, tc.get("id")), opt_str(c, fn->get("name")), keep(c, a)});
            }
            q.calls = c->calls[i].data();
            q.n_calls = (int)c->calls[i].size();
        }
    }
    if (tools && tools->kind != pyjson_value::NUL) {
        c->has_tools = true;
        pyjson_dump(*tools, &c->tools);
    }
}

/* vllm/renderers/inkling.py _resolve_reasoning_effort: nothing sent is the default, a name its value */
static int effort_of(const pyjson_value *e) {
    if (!e || e->kind == pyjson_value::NUL) return inkling_effort_default();
    const int centi = inkling_effort_named(e->s.c_str());
    if (centi < 0) {
        fprintf(stderr, "inkling_chat_gate: bad effort %s\n", e->s.c_str());
        exit(2);
    }
    return centi;
}

static bool render(const conv &c, int effort, bool gen, inkling_render_out *out, std::string *refusal) {
    inkling_render_in in;
    in.msgs = c.msgs.data();
    in.n_msgs = (int)c.msgs.size();
    in.tools_json = c.has_tools ? c.tools.c_str() : NULL;
    in.effort = effort;
    in.add_generation_prompt = gen;
    char err[400];
    if (inkling_chat_render(in, out, err, sizeof err)) return true;
    const char *colon = strchr(err, ':');
    refusal->assign(err, colon ? (size_t)(colon - err) : strlen(err));
    return false;
}

/* ---- R1 / R2 ------------------------------------------------------------------------------------------ */

static void r1_hand(const bpe_tokenizer *t, const std::string &dir) {
    const pyjson_value v = load_json(dir + "/render_cases.json");
    int bad = 0, refusals = 0, guarded = 0;
    for (const auto &c : v.a) {
        const std::string &name = c.get("name")->s;
        conv cv;
        build_conv(*c.get("messages"), c.get("tools"), &cv);
        inkling_render_out out;
        std::string refusal;
        const bool ok = render(cv, effort_of(c.get("effort")), c.get("gen")->b, &out, &refusal);
        const pyjson_value &want = *c.get("expect");
        g_checks++;
        if (want.get("refusal")) {
            refusals++;
            if (ok) {
                bad++;
                fail("R1 %s: rendered, vLLM raises %s", name.c_str(), want.get("refusal")->s.c_str());
            }
            continue;
        }
        if (!ok) {
            bad++;
            fail("R1 %s: refused (%s)", name.c_str(), refusal.c_str());
            continue;
        }
        if (out.text != want.get("text")->s) {
            bad++;
            fail("R1 %s: text differs", name.c_str());
            continue;
        }
        const std::vector<int> got = encode(t, out.text, &out.spans);
        g_checks++;
        if (got != json_ids(*want.get("guarded_ids"))) {
            bad++;
            fail("R1 %s: guarded ids: %s", name.c_str(), first_diff(got, json_ids(*want.get("guarded_ids"))).c_str());
        }
        const bool same = want.get("vllm_ids_equal")->b;
        guarded += !same;
        if (same) {
            g_checks++;
            if (got != json_ids(*want.get("ids"))) {
                bad++;
                fail("R1 %s: ids differ from vLLM's", name.c_str());
            }
        }
    }
    /* the effort map's text: vLLM's f"{v:.2f}" with trailing zeros dropped, "0.0" for zero */
    static const struct { const char *name; const char *text; } eff[] = {
        {"none", "0.0"}, {"minimal", "0.1"}, {"low", "0.2"}, {"medium", "0.7"}, {"high", "0.9"}, {"xhigh", "0.99"},
        {"max", "0.99"},
    };
    for (const auto &e : eff) {
        std::string s;
        CHECK(inkling_effort_text(inkling_effort_named(e.name), &s) && s == e.text, "effort %s renders %s", e.name,
              s.c_str());
    }
    std::string s;
    CHECK(inkling_effort_text(5, &s) && s == "0.05", "effort 5 renders %s", s.c_str());
    CHECK(!inkling_effort_text(100, &s) && !inkling_effort_text(-1, &s), "effort outside [0, 99] renders");
    CHECK(inkling_effort_default() == 90 && inkling_effort_named("ultra") < 0, "default / unknown effort");
    printf("R1 render hand cases: %zu (%d refusals, %d where the span guard departs from vLLM's ids), "
           "%d mismatched\n", v.a.size(), refusals, guarded, bad);
}

static void r2_corpus(const bpe_tokenizer *t, const std::string &dir, const std::string &cases_dir) {
    std::string tsv;
    if (!read_file(dir + "/render_corpus.tsv", &tsv)) { fail("R2: no render_corpus.tsv"); return; }
    static const char *const efforts[] = {"none", "low", "medium", NULL, "max"};
    int lines = 0, bad = 0, total = 0, rendered = 0;
    long tokens = 0;
    for (size_t pos = 0; pos < tsv.size();) {
        const size_t nl = tsv.find('\n', pos);
        const std::string line = tsv.substr(pos, nl - pos);
        pos = nl + 1;
        if (line.empty() || line[0] == '#') continue;
        char file[256], cfg[4], refusals[256], sha_text[64], sha_ids[64];
        int n = 0, ok = 0;
        long ntok = 0;
        if (sscanf(line.c_str(), "%255s\t%3s\t%d\t%d\t%255s\t%63s\t%63s\t%ld", file, cfg, &n, &ok, refusals, sha_text,
                   sha_ids, &ntok) != 8)
            continue;
        const pyjson_value cases = load_json(cases_dir + "/" + file);
        std::string ht, hi;
        int got_ok = 0;
        long got_tok = 0;
        for (size_t idx = 0; idx < cases.a.size(); idx++) {
            const pyjson_value &c = cases.a[idx];
            conv cv;
            const pyjson_value *tools = c.get("tools");
            build_conv(*c.get("messages"), tools && tools->kind == pyjson_value::ARR && !tools->a.empty() ? tools : NULL,
                       &cv);
            pyjson_value e;
            const char *en = cfg[0] == 'A' ? NULL : efforts[idx % 5];
            if (en) {
                e.kind = pyjson_value::STR;
                e.s = en;
            }
            inkling_render_out out;
            std::string refusal;
            char head[32];
            if (!render(cv, effort_of(&e), cfg[0] == 'B', &out, &refusal)) {
                snprintf(head, sizeof head, "%zu refuse\n", idx);
                ht += head;
                continue;
            }
            got_ok++;
            snprintf(head, sizeof head, "%zu ", idx);
            ht += head + out.text + "\n";
            const std::vector<int> ids = encode(t, out.text, &out.spans);
            std::string s = head;
            for (size_t k = 0; k < ids.size(); k++) {
                char b[16];
                snprintf(b, sizeof b, "%s%d", k ? "," : "", ids[k]);
                s += b;
            }
            hi += s + "\n";
            got_tok += (long)ids.size();
        }
        lines++;
        total += n;
        rendered += got_ok;
        tokens += got_tok;
        g_checks++;
        if (got_ok != ok || sha1_hex(ht) != sha_text || sha1_hex(hi) != sha_ids || got_tok != ntok) {
            bad++;
            fail("R2 %s config %s: %d rendered vs %d, text %s, ids %s", file, cfg, got_ok, ok,
                 sha1_hex(ht) == sha_text ? "same" : "DIFFER", sha1_hex(hi) == sha_ids ? "same" : "DIFFER");
        }
    }
    printf("R2 render corpus: %d file x config lines, %d cases, %d rendered, %ld tokens, %d mismatched\n", lines,
           total, rendered, tokens, bad);
}

/* ---- P1 / P2: the output parser ------------------------------------------------------------------------ */

struct reading {
    std::string reasoning, content;
    std::vector<out_call> calls;
    int errors = 0;
    std::string why;   ///< what was inconsistent in the event stream, or empty
};

/* Parse one sampled turn with the input cut at `cuts`, and check the events against the final reading: the
 * text deltas concatenate to it; each call's TOOL_ARGS fragments plus "}" are its arguments. */
static reading run_parser(const std::string &out, const std::vector<size_t> &cuts) {
    inkling_output_parser p;
    p.init(OUT_HEADER);
    std::vector<out_event> ev;
    size_t at = 0;
    for (size_t c : cuts) {
        p.feed(out.data() + at, c - at, &ev);
        at = c;
    }
    p.feed(out.data() + at, out.size() - at, &ev);
    p.finish(&ev);
    reading r;
    r.reasoning = p.reasoning();
    r.content = p.content();
    r.calls = p.calls();
    r.errors = p.errors();
    std::string rs, cs;
    std::map<int, std::string> args;
    std::map<int, bool> begun;
    size_t ended = 0;
    for (const out_event &e : ev) {
        switch (e.kind) {
        case out_event::REASONING: rs += e.text; break;
        case out_event::CONTENT: cs += e.text; break;
        case out_event::TOOL_BEGIN: begun[e.index] = true; break;
        case out_event::TOOL_ARGS:
            if (!begun[e.index]) r.why = "TOOL_ARGS before TOOL_BEGIN";
            args[e.index] += e.text;
            break;
        case out_event::TOOL_END: {
            const std::string streamed = args.count(e.index) ? args[e.index] + "}" : "{}";
            if (!begun[e.index]) r.why = "TOOL_END without TOOL_BEGIN";
            else if (streamed != e.arguments) r.why = "the streamed arguments are not the call's";
            ended++;
            break;
        }
        case out_event::ERROR: break;
        }
    }
    if (rs != r.reasoning) r.why = "the reasoning deltas are not the reasoning";
    if (cs != r.content) r.why = "the content deltas are not the content";
    if (ended != r.calls.size()) r.why = "TOOL_END count is not the call count";
    return r;
}

static std::vector<std::vector<size_t>> chunkings(size_t n, unsigned seed) {
    std::vector<std::vector<size_t>> out(3);
    for (size_t i = 1; i < n; i++) out[1].push_back(i);
    std::mt19937 rng(seed);
    for (size_t i = 1; i < n; i += 1 + rng() % 7) out[2].push_back(i);
    return out;
}

static std::string reading_line(const reading &r) {
    pyjson_value v;
    v.kind = pyjson_value::ARR;
    pyjson_value s;
    s.kind = pyjson_value::STR;
    s.s = r.reasoning;
    v.a.push_back(s);
    s.s = r.content;
    v.a.push_back(s);
    pyjson_value calls;
    calls.kind = pyjson_value::ARR;
    for (const out_call &c : r.calls) {
        pyjson_value one;
        one.kind = pyjson_value::ARR;
        s.s = c.name;
        one.a.push_back(s);
        s.s = c.arguments;
        one.a.push_back(s);
        calls.a.push_back(one);
    }
    v.a.push_back(calls);
    std::string line;
    pyjson_dump(v, &line);
    return line + "\n";
}

/* vLLM accepts a call the turn ended inside (its args carved from the unterminated wrapper); the kit's one
 * rule for every family is that such a call is broken (an ERROR, the shared retry).  The only departure. */
static bool ends_inside_call(const std::string &out) {
    const size_t open = out.rfind("<|content_invoke_tool_json|>");
    return open != std::string::npos && out.find("<|end_message|>", open) == std::string::npos &&
           out.find("<|content_model_end_sampling|>", open) == std::string::npos;
}

static void p1_units(const std::string &dir) {
    const pyjson_value v = load_json(dir + "/parse_cases.json");
    int bad = 0, departs = 0, malformed = 0;
    for (size_t i = 0; i < v.a.size(); i++) {
        const std::string &text = v.a[i].get("text")->s;
        const pyjson_value &want = *v.a[i].get("expect");
        std::vector<out_call> wcalls;
        for (const auto &c : want.get("calls")->a)
            wcalls.push_back({c.get("name")->s, c.get("arguments")->s});
        const bool inside = ends_inside_call(text);
        if (inside) {
            departs++;
            wcalls.pop_back();
        }
        for (const auto &cuts : chunkings(text.size(), (unsigned)i)) {
            const reading r = run_parser(text, cuts);
            g_checks++;
            bool same = r.reasoning == want.get("reasoning")->s && r.content == want.get("content")->s &&
                        r.calls.size() == wcalls.size() && r.why.empty() && (!inside || r.errors == 1);
            for (size_t k = 0; same && k < wcalls.size(); k++)
                same = r.calls[k].name == wcalls[k].name && r.calls[k].arguments == wcalls[k].arguments;
            if (!same) {
                bad++;
                std::string q;
                pyjson_dump_string(text.data(), std::min<size_t>(text.size(), 100), &q);
                fail("P1 %s (%zu cuts): reasoning %s content %s calls %zu/%zu errors %d %s", q.c_str(), cuts.size(),
                     r.reasoning == want.get("reasoning")->s ? "same" : "DIFFER",
                     r.content == want.get("content")->s ? "same" : "DIFFER", r.calls.size(), wcalls.size(), r.errors,
                     r.why.c_str());
                break;
            }
            if (cuts.empty()) malformed += r.errors > 0;
        }
    }
    printf("P1 output parser units: %zu outputs x 3 chunkings (%d with a malformed call, %d ending inside a call: "
           "broken by the shared rule where vLLM keeps it), %d mismatched\n", v.a.size(), malformed, departs, bad);
}

static void p2_corpus(const std::string &dir, const std::string &cases_dir) {
    std::string tsv;
    if (!read_file(dir + "/parse_corpus.tsv", &tsv)) { fail("P2: no parse_corpus.tsv"); return; }
    static const char kModel[] = "<|message_model|>", kEnd[] = "<|content_model_end_sampling|>";
    int files = 0, bad = 0, turns = 0, with_calls = 0;
    for (size_t pos = 0; pos < tsv.size();) {
        const size_t nl = tsv.find('\n', pos);
        const std::string line = tsv.substr(pos, nl - pos);
        pos = nl + 1;
        if (line.empty() || line[0] == '#') continue;
        char file[256], sha[64];
        int n = 0;
        if (sscanf(line.c_str(), "%255s\t%d\t%63s", file, &n, sha) != 3) continue;
        const pyjson_value cases = load_json(cases_dir + "/" + file);
        std::string h[3];
        int got = 0;
        for (const auto &c : cases.a) {
            for (const auto &m : c.get("messages")->a) {
                const pyjson_value *role = m.get("role");
                if (!role || role->s != "assistant") continue;
                pyjson_value one;
                one.kind = pyjson_value::ARR;
                one.a.push_back(m);
                conv cv;
                build_conv(one, NULL, &cv);
                inkling_render_out out;
                std::string refusal;
                if (!render(cv, 0, false, &out, &refusal)) continue;
                /* the turn as sampled: past the effort block and the prompt's <|message_model|>, before the stop */
                const size_t at = out.text.find(kModel, out.text.find("<|end_message|>") + 1);
                const std::string &tx = out.text;
                if (tx.size() < strlen(kEnd) || tx.compare(tx.size() - strlen(kEnd), strlen(kEnd), kEnd)) continue;
                if (at == std::string::npos) continue;   /* an empty turn: nothing before the stop token */
                const std::string turn = tx.substr(at + strlen(kModel), tx.size() - strlen(kEnd) - at - strlen(kModel));
                const auto cuts = chunkings(turn.size(), (unsigned)got);
                for (int k = 0; k < 3; k++) {
                    const reading r = run_parser(turn, cuts[(size_t)k]);
                    if (!r.why.empty()) fail("P2 %s: %s", file, r.why.c_str());
                    h[k] += reading_line(r);
                    if (k == 0) with_calls += !r.calls.empty();
                }
                got++;
            }
        }
        files++;
        turns += got;
        g_checks++;
        if (got != n || sha1_hex(h[0]) != sha || h[1] != h[0] || h[2] != h[0]) {
            bad++;
            fail("P2 %s: %d turns vs %d, readings %s, chunkings %s", file, got, n,
                 sha1_hex(h[0]) == sha ? "same" : "DIFFER", h[1] == h[0] && h[2] == h[0] ? "same" : "DIFFER");
        }
    }
    printf("P2 output parser corpus: %d files, %d assistant turns (%d with tool calls), whole / byte-by-byte / random "
           "chunking; %d mismatched\n", files, turns, with_calls, bad);
}

/* ---- S1: the pieces a live conversation appends (L294 E6: the server's suffix hooks, the engine's chat front) -- */

static std::string render_n(const conv &c, int n, int effort, bool gen, bool *ok) {
    inkling_render_in in;
    in.msgs = c.msgs.data();
    in.n_msgs = n;
    in.tools_json = c.has_tools ? c.tools.c_str() : NULL;
    in.effort = effort;
    in.add_generation_prompt = gen;
    inkling_render_out out;
    char err[400];
    *ok = inkling_chat_render(in, &out, err, sizeof err);
    return out.text;
}

/* One conversation: at every assistant message j, the prompt before it + the turn as sampled + the piece up to
 * the next assistant message == the full render through that piece; the parser's raw span of the sampled turn is
 * the call-block finder's key, found where the turn sits in the transcript; and the turn replayed from those
 * bytes renders exactly as the canonical turn.  Returns the compositions checked; `why` = the first failure. */
static int g_s1_keyed = 0;   /* tool-call turns whose raw span was keyed and replayed */

static int s1_conversation(const conv &c, int effort, std::string *why) {
    const int n = (int)c.msgs.size();
    int checked = 0;
    for (int j = 0; j < n && why->empty(); j++) {
        const inkling_msg_in &a = c.msgs[(size_t)j];
        if (!a.role || strcmp(a.role, "assistant")) continue;
        int k = j + 1;
        while (k < n && strcmp(c.msgs[(size_t)k].role ? c.msgs[(size_t)k].role : "", "assistant")) k++;
        bool ok_full = false, ok_prefix = false;
        const std::string full = render_n(c, k, effort, true, &ok_full);
        const std::string prefix = render_n(c, j, effort, true, &ok_prefix);
        if (!ok_full) continue;   /* a refusal: R1 / R2 grade those */
        inkling_render_out turn, tail;
        char err[400];
        if (!inkling_chat_render_assistant_turn(a, &turn, err, sizeof err)) {
            if (!strncmp(err, "empty_turn", 10)) continue;
            *why = std::string("assistant turn refused: ") + err;
            break;
        }
        const bool calls = a.n_calls > 0;
        if (!inkling_chat_render_turn(c.msgs.data(), k, j + 1, calls, true, &tail, err, sizeof err)) {
            *why = std::string("tail refused: ") + err;
            break;
        }
        if (!ok_prefix || prefix + turn.text + tail.text != full) {
            *why = "prefix + turn + tail != the full render at message " + std::to_string(j);
            break;
        }
        /* the spans shift with the cut: every client byte of the full render is client in the pieces */
        for (const pulsar_text_span &s : turn.spans)
            if (s.hi > turn.text.size() || s.lo >= s.hi) *why = "a turn span outside the turn";
        checked++;
        if (!calls) continue;
        /* the turn as the model sampled it: before its stop token (a call turn has none in its render) */
        inkling_output_parser p;
        p.init(OUT_HEADER);
        std::vector<out_event> ev;
        p.feed(turn.text.data(), turn.text.size(), &ev);
        p.finish(&ev);
        size_t lo = 0, hi = 0;
        if (!p.raw_span(&lo, &hi) || (int)p.calls().size() != a.n_calls) {
            if (p.errors() == 0) *why = "the parser read no calls back from the turn at message " + std::to_string(j);
            continue;   /* a call the shared JSON body refuses (vLLM's too): no key */
        }
        const std::string raw = turn.text.substr(lo, hi - lo);
        const char *end = NULL;
        const char *key = inkling_find_call_block(raw.c_str(), &end);
        if (key != raw.c_str() || end != raw.c_str() + raw.size()) {
            *why = "the raw span is not one call-block run at message " + std::to_string(j);
            break;
        }
        const std::string live = prefix + turn.text;
        const char *at = inkling_find_call_block(live.c_str() + prefix.size() - strlen("<|message_model|>"), &end);
        if (!at || std::string(at, (size_t)(end - at)) != raw || (size_t)(at - live.c_str()) != prefix.size() + lo) {
            *why = "the finder does not key the turn's calls in the transcript at message " + std::to_string(j);
            break;
        }
        inkling_msg_in replay = a;
        replay.raw_calls = raw.c_str();
        inkling_render_out again;
        if (!inkling_chat_render_assistant_turn(replay, &again, err, sizeof err) || again.text != turn.text) {
            *why = "the raw replay of a canonical turn differs from it at message " + std::to_string(j);
            break;
        }
        g_s1_keyed++;
    }
    return checked;
}

static void s1_hand(void) {
    /* the sampled bytes replay verbatim (a spelling the canonical render would normalise), in the full render
     * and the sampled turn alike; text sampled between two calls is no run, so that turn renders canonically */
    const inkling_tool_call_in calls[2] = {{"c1", "get_weather", "{\"city\": \"Paris\"}"},
                                           {"c2", "get_weather", "{\"city\":\"Rome\"}"}};
    const std::string raw = "get_weather<|content_invoke_tool_json|>{\"name\": \"get_weather\", \"args\": {\"city\": "
                            "\"Paris\"}}<|end_message|><|message_model|>get_weather<|content_invoke_tool_json|>"
                            "{\"name\":\"get_weather\",\"args\":{\"city\":\"Rome\"}}<|end_message|>";
    inkling_msg_in a = {};
    a.role = "assistant";
    a.reasoning = "Both.";
    a.calls = calls;
    a.n_calls = 2;
    a.raw_calls = raw.c_str();
    inkling_render_out turn;
    char err[300];
    CHECK(inkling_chat_render_assistant_turn(a, &turn, err, sizeof err) &&
              turn.text == "<|content_thinking|>Both.<|end_message|><|message_model|>" + raw,
          "S1: the sampled turn with raw calls is %s", turn.text.c_str());
    const char *end = NULL;
    const char *k = inkling_find_call_block(turn.text.c_str(), &end);
    CHECK(k && std::string(k, (size_t)(end - k)) == raw, "S1: the finder keys the raw run in the turn");
    CHECK(inkling_find_call_block(end, &end) == NULL, "S1: nothing after the run");
    const std::string between = "get_weather<|content_invoke_tool_json|>{\"name\":\"get_weather\",\"args\":{}}"
                                "<|end_message|><|message_model|><|content_text|>and<|end_message|><|message_model|>"
                                "get_weather<|content_invoke_tool_json|>{\"name\":\"get_weather\",\"args\":{}}"
                                "<|end_message|>";
    k = inkling_find_call_block(between.c_str(), &end);
    CHECK(k == between.c_str() && end < between.c_str() + between.size(), "S1: text between calls ends the run");
    a.raw_calls = between.c_str();
    CHECK(inkling_chat_render_assistant_turn(a, &turn, err, sizeof err) && turn.text.find("and") == std::string::npos &&
              turn.text.find("{\"name\":\"get_weather\",\"args\":{\"city\":\"Paris\"}}") != std::string::npos,
          "S1: a raw span that is not one run renders canonically");
    CHECK(inkling_find_call_block("x<|message_model|>a<|content_invoke_tool_json|>{", &end) == NULL,
          "S1: an unclosed block is no key");
    CHECK(inkling_find_call_block("<|message_user|>a<|content_invoke_tool_json|>{}<|end_message|>", &end) == NULL,
          "S1: a call kind after another role's marker is no key");
    /* refusals */
    inkling_msg_in empty = {};
    empty.role = "assistant";
    CHECK(!inkling_chat_render_assistant_turn(empty, &turn, err, sizeof err) && !strncmp(err, "empty_turn", 10),
          "S1: an empty turn has no sampled render");
    inkling_msg_in noc = {};
    noc.role = "assistant";
    noc.content = "x";
    noc.raw_calls = raw.c_str();
    CHECK(!inkling_chat_render_assistant_turn(noc, &turn, err, sizeof err) && !strncmp(err, "raw_calls_without_calls", 23),
          "S1: raw calls without calls refuse");
    inkling_msg_in norole = {};
    norole.content = "x";
    CHECK(!inkling_chat_render_turn(&norole, 1, 0, false, false, &turn, err, sizeof err) &&
              !strncmp(err, "unexpected_role", 15), "S1: a message with no role refuses (unexpected_role)");
    CHECK(!inkling_chat_render_turn(NULL, 0, 0, false, false, &turn, err, sizeof err), "S1: an empty piece refuses");
    CHECK(inkling_chat_render_turn(NULL, 0, 0, true, false, &turn, err, sizeof err) &&
              turn.text == "<|content_model_end_sampling|>", "S1: the close alone");
    /* a tail's tool result is authored by the call it answers, named in a message before the tail */
    inkling_msg_in two[2] = {};
    two[0].role = "assistant";
    two[0].calls = calls;
    two[0].n_calls = 2;
    two[1].role = "tool";
    two[1].content = "22C";
    two[1].tool_call_id = "c2";
    CHECK(inkling_chat_render_turn(two, 2, 1, true, true, &turn, err, sizeof err) &&
              turn.text == "<|content_model_end_sampling|><|message_tool|>get_weather<|content_text|>22C<|end_message|>"
                           "<|message_model|>",
          "S1: the tail is %s", turn.text.c_str());
}

static void s1_corpus(const std::string &dir, const std::string &cases_dir) {
    std::string tsv;
    if (!read_file(dir + "/render_corpus.tsv", &tsv)) { fail("S1: no render_corpus.tsv"); return; }
    int files = 0, convs = 0, checked = 0, bad = 0;
    std::string last;
    for (size_t pos = 0; pos < tsv.size();) {
        const size_t nl = tsv.find('\n', pos);
        const std::string line = tsv.substr(pos, nl - pos);
        pos = nl + 1;
        char file[256], cfg[4];
        if (line.empty() || line[0] == '#' || sscanf(line.c_str(), "%255s\t%3s", file, cfg) != 2) continue;
        if (last == file) continue;   /* one pass a file (the two configurations render the same messages) */
        last = file;
        const pyjson_value cases = load_json(cases_dir + "/" + file);
        for (size_t idx = 0; idx < cases.a.size(); idx++) {
            const pyjson_value &c = cases.a[idx];
            conv cv;
            const pyjson_value *tools = c.get("tools");
            build_conv(*c.get("messages"), tools && tools->kind == pyjson_value::ARR && !tools->a.empty() ? tools : NULL,
                       &cv);
            std::string why;
            checked += s1_conversation(cv, (int)(idx % 3) * 45, &why);   /* efforts 0, 45, 90 */
            convs++;
            g_checks++;
            if (!why.empty()) {
                bad++;
                fail("S1 %s case %zu: %s", file, idx, why.c_str());
            }
        }
        files++;
    }
    printf("S1 live pieces: %d files, %d conversations, %d turns composed (prompt + sampled turn + tail == full "
           "render), %d tool-call turns keyed (raw span == the finder's key; raw replay == canonical), %d failed\n", files,
           convs, checked, g_s1_keyed, bad);
}

int main(int argc, char **argv) {
    std::string tok_dir, vec_dir, cases_dir, calib;
    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        if (a == "--tok" && i + 1 < argc) tok_dir = argv[++i];
        else if (a == "--vectors" && i + 1 < argc) vec_dir = argv[++i];
        else if (a == "--cases" && i + 1 < argc) cases_dir = argv[++i];
        else if (a == "--calib" && i + 1 < argc) calib = argv[++i];
        else tok_dir.clear(), i = argc;
    }
    if (tok_dir.empty() || vec_dir.empty()) {
        fprintf(stderr, "usage: inkling_chat_gate --tok DIR --vectors DIR [--cases DIR] [--calib FILE]\n");
        return 2;
    }
    std::string ranks, cfg, eos;
    if (!read_file(tok_dir + "/tiktoken/tokenizer.model", &ranks) ||
        !read_file(tok_dir + "/tokenizer_config.json", &cfg) || !read_file(tok_dir + "/config.json", &eos)) {
        fprintf(stderr, "inkling_chat_gate: %s must hold tiktoken/tokenizer.model, tokenizer_config.json and "
                        "config.json\n", tok_dir.c_str());
        return 2;
    }
    char err[512];
    bpe_tokenizer *t = bpe_tokenizer_load_tiktoken(ranks.data(), ranks.size(), "o200k", cfg.data(), cfg.size(),
                                                   eos.data(), eos.size(), err, sizeof err);
    if (!t) {
        fprintf(stderr, "inkling_chat_gate: %s\n", err);
        return 1;
    }
    const pyjson_value meta = load_json(vec_dir + "/meta.json");
    printf("inkling_chat_gate: tokenizer %s/tiktoken/tokenizer.model (%d ids), goldens from tokenizers %s, "
           "vLLM %.12s\n", tok_dir.c_str(), bpe_tokenizer_n_tokens(t), meta.get("tokenizers")->s.c_str(),
           meta.get("vllm")->s.c_str());
    t0_configuration(t, tok_dir, meta);
    t1_adversarial(t, vec_dir);
    t2_spans(t, vec_dir);
    t3_sweep(t, vec_dir, inkling_sweep_context);
    if (!calib.empty()) t4_calib(t, vec_dir, calib);
    else printf("T4 corpus: SKIPPED (no --calib)\n");
    r1_hand(t, vec_dir);
    p1_units(vec_dir);
    s1_hand();
    if (!cases_dir.empty()) {
        r2_corpus(t, vec_dir, cases_dir);
        p2_corpus(vec_dir, cases_dir);
        s1_corpus(vec_dir, cases_dir);
    } else {
        printf("R2 render corpus / P2 parser corpus / S1 live pieces: SKIPPED (no --cases)\n");
    }
    bpe_tokenizer_free(t);
    printf("\ninkling_chat_gate: %d checks, %d failed -- %s\n", g_checks, g_fail, g_fail ? "FAIL" : "PASS");
    return g_fail ? 1 : 0;
}
